package mx.com.mesaregia.inventario.api.controller;
import jakarta.validation.Valid; import mx.com.mesaregia.inventario.application.service.ReservaService; import mx.com.mesaregia.inventario.api.request.*; import mx.com.mesaregia.inventario.api.response.ReservaResponse; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.http.HttpStatus; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/v1/reservas") @ConditionalOnProperty(prefix="mesaregia.internal-endpoints",name="enabled",havingValue="true") public class InternalReservaController {private final ReservaService s;public InternalReservaController(ReservaService s){this.s=s;} @PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("isAuthenticated()") public ReservaResponse crear(@RequestHeader("Idempotency-Key")String key,@Valid @RequestBody ReservaCrearRequest r){return s.crearConfirmada(key,r);}@PostMapping("/ordenes/{idOrden}/liberar")@PreAuthorize("isAuthenticated()")public ReservaResponse liberar(@PathVariable Long idOrden,@Valid @RequestBody ReservaLiberarRequest r){return s.liberarPorOrden(idOrden,r);} }
